// Function to compute the common elements in two arrays

function common_elements(a, b) {
	return a.filter(el => b.includes(el));
}

// Function to get the list of common elements in two arrays

function get_common_elements(a, b) {
	let result = [];
	let i = 0;
	let j = 0;

	while (i < a.length && j < b.length) {
		if (a[i] > b[j]) {
			j++;
		} else if (a[i] < b[j]) {
			i++;
		} else {
			result.push(a[i]);
			i++;
			j++;
		}
	}

	return result;
}


 

// Test the function with two arrays

let a = [1, 2, 3, 4, 5];
let b = [3, 4, 5, 6, 7];

console.log(common_elements(a, b)); // [3, 4, 5]
console.log(get_common_elements(a, b)); // [3, 4, 5]
